import type { Card, NewCard, Review, Rating, DeckStat, Deck, NewDeck } from '@motivation/shared';
import { API_URL } from '../config.js';
import { isApiReachable } from '../db/api-reachability.js';
import { apiError, createJsonClient } from './http.js';

export type { DeckStat };

const VIETNAMESE_ROOT = `${API_URL}/api/sections/vietnamese`;
const api = createJsonClient(VIETNAMESE_ROOT);

export class VietnameseService {
    /**
     * Review scheduling runs on the server only (the offline router answers POST /review with 503),
     * so a session asks first instead of failing every rating (story 379, explore-09).
     */
    static async isReviewReachable(): Promise<boolean> {
        return isApiReachable();
    }

    /**
     * Fetch FSRS cards that are due for review.
     * @param limit maximum number of cards to fetch
     * @returns list of cards ready to be reviewed
     */
    static async getDueReviewCards(limit: number = 20): Promise<Card[]> {
        return api.get<Card[]>(`/review?limit=${limit}`);
    }

    static async getDeckStats(): Promise<DeckStat[]> {
        return api.get<DeckStat[]>('/decks/stats');
    }

    static async createDeck(payload: Pick<NewDeck, 'name' | 'description'>): Promise<Deck> {
        return api.post<Deck>('/decks', payload);
    }

    static async updateDeck(id: string, payload: Partial<Pick<Deck, 'name' | 'description'>>): Promise<Deck> {
        return api.patch<Deck>(`/decks/${encodeURIComponent(id)}`, payload);
    }

    static async deleteDeck(id: string): Promise<void> {
        await api.del(`/decks/${encodeURIComponent(id)}`);
    }

    static async getCardsByDeck(deckId: string): Promise<Card[]> {
        return api.get<Card[]>(`/decks/${encodeURIComponent(deckId)}/cards`);
    }

    static async createCard(deckId: string, payload: Pick<NewCard, 'front' | 'back' | 'notes'>): Promise<Card> {
        return api.post<Card>(`/decks/${encodeURIComponent(deckId)}/cards`, payload);
    }

    static async updateCard(id: string, payload: Partial<Pick<Card, 'front' | 'back' | 'notes'>>): Promise<Card> {
        return api.patch<Card>(`/cards/${encodeURIComponent(id)}`, payload);
    }

    /** Bypasses the JSON client: the body is multipart. */
    static async uploadCardAudio(id: string, file: File): Promise<Card> {
        const formData = new FormData();
        formData.append('audio', file);
        const path = `/cards/${encodeURIComponent(id)}/audio`;
        const response = await fetch(`${VIETNAMESE_ROOT}${path}`, { method: 'PUT', body: formData });
        if (!response.ok) throw await apiError(response, `PUT ${path}`);
        return response.json() as Promise<Card>;
    }

    /** Bypasses the JSON client: this DELETE answers the updated card. */
    static async deleteCardAudio(id: string): Promise<Card> {
        const path = `/cards/${encodeURIComponent(id)}/audio`;
        const response = await fetch(`${VIETNAMESE_ROOT}${path}`, { method: 'DELETE' });
        if (!response.ok) throw await apiError(response, `DELETE ${path}`);
        return response.json() as Promise<Card>;
    }

    static async deleteCard(id: string): Promise<void> {
        await api.del(`/cards/${encodeURIComponent(id)}`);
    }

    /**
     * Submit a rating (1-4) for a flashcard to update its FSRS scheduling.
     * @param cardId the ID of the card being reviewed
     * @param rating the score given (1=Again, 2=Hard, 3=Good, 4=Easy)
     * @returns the updated review state
     */
    static async submitReview(cardId: string, rating: Rating): Promise<Review> {
        return api.post<Review>('/review', { card_id: cardId, rating });
    }
}
